    'facebook.com': "Access to Facebook is blocked",
    'twitter.com': "Twitter is not available at this time",
    'youtube.com': "YouTube access is restricted",
    'netflix.com': "Netflix is blocked on this network"
}

@app.route('/', defaults={'path': ''})
